// The editor: object list, property panels, timeline, dialogs. Plain DOM code, no framework.
import { TTFLoader } from 'three/addons/loaders/TTFLoader.js';
import { Engine, evalPose, evalCamera } from './engine.js';
import { newProject, newObject, normalize, clone, uid, SIZES, snap, keyAt, upsertKey, History } from './model.js';
import { FONTS, SHAPES, SOLIDS, STYLES, EASE, IN_FX, LOOP_FX, PARTICLES } from './assets.js';
import { TEMPLATES } from './templates.js';
import { exportImage, exportVideo, exportGIF } from './exporter.js';

const $ = s => document.querySelector(s);
function h(tag, attrs, ...kids) {
  const el = document.createElement(tag);
  for (const k in attrs || {}) {
    const v = attrs[k];
    if (v === false || v == null) continue;
    if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
    else if (k === 'class') el.className = v; else if (k === 'style') el.style.cssText = v;
    else if (k === 'value' || k === 'checked' || k === 'disabled' || k === 'innerHTML') el[k] = v;
    else el.setAttribute(k, v === true ? '' : v);
  }
  put(el, ...kids);
  return el;
}
function put(el, ...kids) { el.append(...kids.flat(3).filter(x => x != null && x !== false)); }
const fmt = v => String(Math.round(v * 1000) / 1000);
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
const AUTOSAVE = 'aik3d.autosave';

const S = { p: null, sel: null, time: 0, playing: false, tab: 'object', key: null, mode: 'translate' };
const engine = new Engine($('#view'));
let hist = new History();
window.aik = { S, engine };                                   // handy in the browser console

const fps = () => S.p.stage.fps;
const selObj = () => S.p.objects.find(o => o.id === S.sel) || null;
const snapshot = () => JSON.stringify({ ...S.p, fonts: undefined });      // fonts are big and never change: keep them out of undo

// ── core update paths ──
function live() { engine.time = S.time; engine.sync(S.p); engine.render(); }
function commit(ui = true) {
  hist.push(snapshot());
  try { localStorage.setItem(AUTOSAVE, JSON.stringify(S.p)); } catch (e) { /* storage full or blocked: the Save button still works */ }
  live(); list(); timeline(); if (ui) panel();
}
function load(p, keepHistory) {
  S.p = normalize(p); S.sel = S.p.objects[0]?.id || null; S.key = null; S.playing = false;
  S.time = snap(S.p.stage.duration * 0.6, fps());
  engine.fonts.clear();
  if (!keepHistory) hist = new History();
  $('#pname').value = S.p.name;
  engine.select(S.sel); fit(); commit();
}
function restore(json) {
  if (!json) return toast('Nothing more to undo/redo');
  const fonts = S.p.fonts; S.p = normalize(JSON.parse(json)); S.p.fonts = fonts;
  if (S.sel !== 'camera' && !selObj()) S.sel = null;
  S.key = null; S.time = Math.min(S.time, S.p.stage.duration); $('#pname').value = S.p.name;
  engine.select(S.sel); fit(); live(); list(); timeline(); panel();
}
function select(id, key = null) { S.sel = id; S.key = key; engine.select(id); engine.render(); list(); timeline(); panel(); }
function setTime(t, light) {
  S.time = Math.max(0, Math.min(S.p.stage.duration, t)); engine.frame(S.time); head();
  if (!light) panel();
}
function toast(msg) { const t = $('#toast'); t.textContent = msg; t.hidden = false; clearTimeout(toast.h); toast.h = setTimeout(() => { t.hidden = true; }, 3200); }

// ── pose editing: writes a keyframe when the object is animated, otherwise the base pose ──
function setPose(o, patch) {
  if (o.keys.length) {
    const cur = evalPose(o, S.time), t = snap(S.time, fps());
    upsertKey(o.keys, { t, pos: [...cur.pos], rot: [...cur.rot], scl: [...cur.scl], op: cur.op, ease: keyAt(o.keys, t, fps())?.ease || 'cubic', ...patch }, fps());
  } else {
    if (patch.pos) o.pos = patch.pos; if (patch.rot) o.rot = patch.rot; if (patch.scl) o.scl = patch.scl; if (patch.op !== undefined) o.opacity = patch.op;
  }
}
function setCam(pos, target) {
  const c = S.p.camera;
  if (c.keys.length) { const t = snap(S.time, fps()); upsertKey(c.keys, { t, pos, target, ease: keyAt(c.keys, t, fps())?.ease || 'cubic' }, fps()); }
  else { c.pos = pos; c.target = target; }
}
engine.onTransform = (id, pos, rot, scl) => { const o = S.p.objects.find(x => x.id === id); if (o) setPose(o, { pos, rot, scl }); };
engine.onTransformEnd = () => commit();
engine.onCamera = (pos, target) => {
  const c = evalCamera(S.p.camera, S.time), same = (a, b) => a.every((v, i) => Math.abs(v - b[i]) < 1e-4);
  if (S.playing || (same(pos, c.pos) && same(target, c.target))) return;          // a plain click must not make a keyframe
  setCam(pos, target); commit(S.sel === 'camera');
};

function addKey() {
  const t = snap(S.time, fps());
  if (S.sel === 'camera') { const c = evalCamera(S.p.camera, S.time); upsertKey(S.p.camera.keys, { t, pos: [...c.pos], target: [...c.target], ease: 'cubic' }, fps()); }
  else {
    const o = selObj(); if (!o) return toast('Pick an object (or the Camera row) first');
    const c = evalPose(o, S.time); upsertKey(o.keys, { t, pos: [...c.pos], rot: [...c.rot], scl: [...c.scl], op: c.op, ease: 'cubic' }, fps());
  }
  S.key = { id: S.sel, t }; S.time = t; commit();
  toast('Keyframe added. Now move the time line, then move the object: a new keyframe is made for you.');
}
const keysOf = id => id === 'camera' ? S.p.camera.keys : S.p.objects.find(o => o.id === id)?.keys;

// ── viewport ──
function fit() {
  const f = $('#frame'), st = S.p.stage, W = f.clientWidth, H = f.clientHeight; if (!W || !H) return;
  const k = Math.min(W / st.width, H / st.height), w = Math.max(2, Math.floor(st.width * k)), hh = Math.max(2, Math.floor(st.height * k));
  const c = $('#view'); c.style.width = w + 'px'; c.style.height = hh + 'px';
  engine.resize(w, hh);
}
new ResizeObserver(() => S.p && fit()).observe($('#frame'));
{
  let down = null; const c = $('#view');
  c.addEventListener('pointerdown', e => { down = engine.gizmo.axis ? null : [e.clientX, e.clientY]; });
  c.addEventListener('pointerup', e => {
    if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 5 || engine.gizmo.dragging) return;
    const id = engine.pick(e.clientX, e.clientY); if (id !== S.sel && (id || S.sel !== 'camera')) select(id);
  });
}
function modes() {
  const el = $('#modes'); el.replaceChildren(
    ...[['translate', 'Move'], ['rotate', 'Rotate'], ['scale', 'Size']].map(([m, label]) => h('button', { class: S.mode === m ? 'on' : '', onclick: () => { S.mode = m; engine.setMode(m); modes(); } }, label)),
    h('button', { title: 'Put the camera back to the front', onclick: () => { setCam([0, 0.6, 13], [0, 0, 0]); commit(); } }, 'Reset view'));
}

// ── left: add buttons + object list ──
function add(o) { S.p.objects.push(o); S.sel = o.id; S.key = null; S.tab = 'object'; engine.select(null); commit(); engine.select(o.id); engine.render(); }
function pickFile(accept, cb) { const f = $('#file'); f.value = ''; f.accept = accept; f.onchange = () => f.files[0] && cb(f.files[0]); f.click(); }
function readImage(file, cb) {
  const url = URL.createObjectURL(file), img = new Image();
  img.onload = () => {            // shrink big photos so the project file and undo stay small
    const k = Math.min(1, 1400 / Math.max(img.width, img.height)), c = h('canvas', { width: Math.round(img.width * k), height: Math.round(img.height * k) });
    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(url); cb(c.toDataURL('image/webp', 0.9));
  };
  img.onerror = () => toast('This picture could not be read'); img.src = url;
}
const importSVG = cb => pickFile('.svg,image/svg+xml', async f => cb(await f.text(), f.name.replace(/\.svg$/i, '')));
function adds() {
  $('#adds').replaceChildren(
    h('button', { onclick: () => add(newObject('text', { text: 'TEXT' })) }, '+ Text'),
    h('button', { onclick: () => add(newObject('shape')) }, '+ Shape'),
    h('button', { onclick: () => add(newObject('solid')) }, '+ 3D solid'),
    h('button', { title: 'Import an SVG logo and make it 3D', onclick: () => importSVG((svg, name) => add(newObject('svg', { svg, name: name.slice(0, 18) || 'Logo' }))) }, '+ SVG logo'),
    h('button', { title: 'Import a PNG or JPG picture', onclick: () => pickFile('image/*', f => readImage(f, image => add(newObject('image', { image, name: f.name.slice(0, 18) })))) }, '+ Picture'),
    h('button', { onclick: () => add(newObject('particles', { kind: 'snow' })) }, '+ Particles'),
    h('button', { title: 'Draw your own shape with points', style: 'grid-column:1/-1', onclick: () => drawDialog(null) }, '✎ Draw a shape'));
}
function list() {
  const P = S.p.objects, el = $('#list');
  const move = (i, d) => { const j = i + d; if (j < 0 || j >= P.length) return; [P[i], P[j]] = [P[j], P[i]]; commit(false); };
  el.replaceChildren(...P.map((o, i) => h('div', { class: 'item' + (o.id === S.sel ? ' sel' : '') + (o.visible ? '' : ' off'), onclick: () => select(o.id) },
    h('span', { class: 'nm' }, o.name), h('span', { class: 'ty' }, o.type === 'particles' ? 'fx' : o.type),
    h('button', { title: o.visible ? 'Hide' : 'Show', 'aria-label': 'Show or hide', onclick: e => { e.stopPropagation(); o.visible = !o.visible; commit(false); } }, o.visible ? '●' : '○'),
    h('button', { title: 'Move up in the list', 'aria-label': 'Move up', onclick: e => { e.stopPropagation(); move(i, -1); } }, '↑'))));
  if (!P.length) put(el, h('p', { class: 'hint' }, 'Empty scene. Add a text or shape above.'));
}
function duplicate() { const o = selObj(); if (!o) return; const c = clone(o); c.id = uid(); c.name = (o.name + ' 2').slice(0, 20); c.pos = [o.pos[0] + 0.4, o.pos[1] - 0.4, o.pos[2]]; add(c); }
function remove() { const o = selObj(); if (!o) return; S.p.objects = S.p.objects.filter(x => x !== o); S.sel = null; S.key = null; engine.select(null); commit(); }

// ── property panel: small field builders ──
const row = (label, ...c) => h('div', { class: 'row' }, h('label', {}, label), ...c);
const sec = t => h('div', { class: 'sec' }, t);
const at = (o, path) => { const ks = path.split('.'), last = ks.pop(), host = ks.reduce((a, k) => a[k], o); return [() => host[last], v => { host[last] = v; }]; };
function slider(label, [get, set], { min = 0, max = 1, step = 0.01 } = {}) {
  const r = h('input', { type: 'range', min, max, step, value: get(), 'aria-label': label }), n = h('input', { type: 'number', step, value: fmt(get()), 'aria-label': label + ' value' });
  const on = (src, done) => { const v = parseFloat(src.value); if (isNaN(v)) return; set(v); if (src === r) n.value = fmt(v); else r.value = v; done ? commit(false) : live(); };
  r.oninput = () => on(r); r.onchange = () => on(r, true); n.oninput = () => on(n); n.onchange = () => on(n, true);
  return row(label, r, n);
}
function color(label, [get, set]) {
  const c = h('input', { type: 'color', value: get(), 'aria-label': label }); c.oninput = () => { set(c.value); live(); }; c.onchange = () => { set(c.value); commit(false); };
  return row(label, c);
}
function choose(label, [get, set], options, ui = true) {
  const s = h('select', { 'aria-label': label, onchange: () => { set(s.value); commit(ui); } }, options.map(o => { const [v, t] = Array.isArray(o) ? o : [o, cap(o)]; return h('option', { value: v }, t); }));
  s.value = get(); return row(label, s);
}
function check(label, [get, set], ui = true) {
  const c = h('input', { type: 'checkbox', checked: !!get(), onchange: () => { set(c.checked); commit(ui); } });
  return h('div', { class: 'row' }, h('label', { style: 'width:auto;display:flex;gap:7px;align-items:center;color:var(--tx);cursor:pointer' }, c, label));
}
function vec(label, o, field, step) {
  const ins = [0, 1, 2].map(i => {
    const n = h('input', { type: 'number', step, value: fmt(evalPose(o, S.time)[field][i]), 'aria-label': label + ' ' + 'XYZ'[i], title: 'XYZ'[i] });
    const on = done => { const v = parseFloat(n.value); if (isNaN(v)) return; const a = [...evalPose(o, S.time)[field]]; a[i] = v; setPose(o, { [field]: a }); done ? commit(false) : live(); };
    n.oninput = () => on(); n.onchange = () => on(true); return n;
  });
  return h('div', { class: 'row row3' }, h('label', {}, label), ...ins);
}

function tabs() {
  $('#tabs').replaceChildren(...[['object', 'Object'], ['style', 'Style'], ['animate', 'Animate'], ['scene', 'Scene']].map(([id, label]) =>
    h('button', { class: S.tab === id ? 'on' : '', onclick: () => { S.tab = id; panel(); } }, label)));
}
function panel() {
  tabs(); const el = $('#panel'), o = selObj(); el.replaceChildren();
  if (S.tab === 'scene') return sceneTab(el);
  if (S.sel === 'camera') return cameraTab(el);
  if (!o) return put(el, h('p', { class: 'hint' }, 'Click an object in the picture or in the list to change it. Use the + buttons to add a new one.'));
  ({ object: objectTab, style: styleTab, animate: animateTab })[S.tab](el, o);
}

function shapeIcon(name) {
  const s = SHAPES[name](), d = [s.getPoints(6), ...s.holes.map(x => x.getPoints(6))].map(pts => 'M' + pts.map(p => fmt(p.x) + ' ' + fmt(-p.y)).join('L') + 'Z').join('');
  return `<svg viewBox="-1.25 -1.25 2.5 2.5" aria-hidden="true"><path fill-rule="evenodd" d="${d}"/></svg>`;
}
function objectTab(el, o) {
  const name = h('input', { type: 'text', value: o.name, maxlength: 24, 'aria-label': 'Name', onchange: () => { o.name = name.value || o.name; commit(false); } });
  put(el, row('Name', name), h('div', { class: 'row' }, h('button', { onclick: duplicate, title: 'Ctrl+D' }, 'Duplicate'), h('button', { onclick: remove, title: 'Delete key' }, 'Delete')));
  const extrude = () => [slider('Depth', at(o, 'depth'), { min: 0.01, max: 3 }), check('Rounded edges (bevel)', at(o, 'bevel.on')),
    o.bevel.on && slider('Bevel size', at(o, 'bevel.size'), { min: 0, max: 0.15, step: 0.005 }), o.bevel.on && slider('Bevel depth', at(o, 'bevel.thick'), { min: 0, max: 0.2, step: 0.005 })];
  if (o.type === 'text') {
    const ta = h('textarea', { rows: 2, 'aria-label': 'Text', spellcheck: 'false' }); ta.value = o.text;
    const auto = s => s.split('\n')[0].slice(0, 18), put2 = () => { if (o.name === auto(o.text) || o.name === 'Text') o.name = auto(ta.value) || 'Text'; o.text = ta.value; };
    ta.oninput = () => { put2(); live(); }; ta.onchange = () => { put2(); name.value = o.name; commit(false); };
    const fonts = [...Object.entries(FONTS).map(([k, v]) => [k, v.label]), ...Object.keys(S.p.fonts).map(k => [k, k + ' (yours)'])];
    put(el, sec('Text'), ta, choose('Font', at(o, 'font'), fonts, false),
      h('div', { class: 'row' }, h('label', {}, ''), h('button', { title: 'Use any TTF or OTF font file from your computer', onclick: () => pickFile('.ttf,.otf', async f => {
        try { const nm = f.name.replace(/\.(ttf|otf)$/i, '').slice(0, 28); S.p.fonts[nm] = new TTFLoader().parse(await f.arrayBuffer()); engine.fonts.delete(nm); o.font = nm; commit(); }
        catch (e) { toast('This font file could not be read'); }
      }) }, '+ Add your font (TTF/OTF)')),
      slider('Size', at(o, 'size'), { min: 0.2, max: 6 }), ...extrude(), slider('Letter gap', at(o, 'spacing'), { min: -0.2, max: 1.5 }),
      slider('Line gap', at(o, 'lineGap'), { min: 0.7, max: 2.5 }), choose('Align', at(o, 'align'), ['left', 'center', 'right'], false));
  } else if (o.type === 'shape') {
    put(el, sec('Shape'), h('div', { class: 'grid shapes' }, Object.keys(SHAPES).map(k => h('button', { class: o.shape === k ? 'on' : '', title: cap(k), 'aria-label': k, innerHTML: shapeIcon(k), onclick: () => { if (o.name === cap(o.shape)) o.name = cap(k); o.shape = k; commit(); } }))),
      slider('Size', at(o, 'size'), { min: 0.2, max: 12 }), ...extrude());
  } else if (o.type === 'solid') {
    put(el, sec('3D solid'), choose('Kind', at(o, 'solid'), SOLIDS, false), slider('Size', at(o, 'size'), { min: 0.2, max: 10 }));
  } else if (o.type === 'svg') {
    put(el, sec(o.draw ? 'Your drawing' : 'SVG logo'), h('div', { class: 'row' },
      o.draw ? h('button', { onclick: () => drawDialog(o) }, '✎ Edit points') : h('button', { onclick: () => importSVG(svg => { o.svg = svg; commit(); }) }, 'Replace SVG file')),
      slider('Size', at(o, 'size'), { min: 0.5, max: 14 }), ...extrude(), !o.draw && check('Keep the colours of the SVG', at(o, 'useColors')));
  } else if (o.type === 'image') {
    put(el, sec('Picture'), h('div', { class: 'row' }, h('button', { onclick: () => pickFile('image/*', f => readImage(f, image => { o.image = image; commit(); })) }, 'Replace picture')),
      slider('Size', at(o, 'size'), { min: 0.5, max: 30 }), h('p', { class: 'hint' }, 'A picture stays flat, but you can move, turn and animate it in 3D.'));
  } else if (o.type === 'particles') {
    const [get] = at(o, 'kind');
    put(el, sec('Particles'), choose('Effect', [get, v => { Object.assign(o, clone(PARTICLES[v]), { kind: v, name: cap(v) }); }], Object.keys(PARTICLES)),
      slider('Amount', at(o, 'count'), { min: 20, max: 4000, step: 10 }), slider('Size', at(o, 'size'), { min: 0.02, max: 1 }), slider('Speed', at(o, 'speed'), { min: 0.1, max: 4 }),
      slider('Area', at(o, 'spread'), { min: 1, max: 50, step: 0.5 }), color('Colour 1', at(o, 'color')), color('Colour 2', at(o, 'color2')), check('Glowing (add light)', at(o, 'additive'), false));
  }
  const p = evalPose(o, S.time);
  put(el, sec('Place' + (o.keys.length ? ' · at this moment (keyframe)' : '')), vec('Position', o, 'pos', 0.1), vec('Rotation °', o, 'rot', 5),
    slider('Scale', [() => p.scl[0], v => setPose(o, { scl: [v, v, v] })], { min: 0.05, max: 5 }),
    slider('Opacity', [() => p.op, v => setPose(o, { op: v })], { min: 0, max: 1 }));
}

function styleTab(el, o) {
  if (!o.mat) return put(el, h('p', { class: 'hint' }, o.type === 'particles' ? 'Particles take their colours from the Object tab.' : 'A picture keeps its own colours. Use Opacity in the Object tab.'));
  const m = o.mat;
  put(el, sec('Quick styles'), h('div', { class: 'grid styles' }, Object.entries(STYLES).map(([k, s]) => h('button', {
    class: 'sw', title: k, 'aria-label': k, style: `background:linear-gradient(160deg,${s.grad ? s.grad[1] + ',' + s.grad[0] : '#fff8 0%,' + s.front + ' 38%,' + s.side});${s.glow ? 'box-shadow:0 0 9px ' + s.emissive : ''}`,
    onclick: () => { o.mat = clone(s); if (o.type === 'svg') o.useColors = false; if (s.glow && !S.p.stage.glow.on) { S.p.stage.glow.on = true; toast('Glow switched on for this neon style (Scene tab)'); } commit(); },
  }))),
    sec('Colours'), !m.grad && color('Front', at(m, 'front')), color('Sides', at(m, 'side')),
    check('Two-colour front (gradient)', [() => !!m.grad, v => { m.grad = v ? [m.side, m.front] : null; }]),
    m.grad && color('Bottom', [() => m.grad[0], v => { m.grad = [v, m.grad[1]]; }]), m.grad && color('Top', [() => m.grad[1], v => { m.grad = [m.grad[0], v]; }]),
    sec('Surface'), slider('Metal', at(m, 'metal')), slider('Roughness', at(m, 'rough')), slider('See-through', [() => 1 - m.opacity, v => { m.opacity = 1 - v; }], { max: 0.95 }),
    sec('Own light'), color('Light colour', at(m, 'emissive')), slider('Strength', at(m, 'glow'), { max: 3 }),
    o.type === 'svg' && o.useColors && !o.draw && h('p', { class: 'hint' }, 'This logo uses the colours of its SVG file. Switch that off in the Object tab to use these colours.'));
}

function animateTab(el, o) {
  const f = o.fx, text = o.type === 'text', fxNames = Object.keys(IN_FX).filter(k => text || k !== 'typewriter');
  if (o.type === 'particles') put(el, h('p', { class: 'hint' }, 'Particles move on their own. Keyframes below can still move the whole effect.'));
  else put(el, 
    sec('1 · Entrance (how it comes in)'), choose('Effect', at(f, 'in.type'), fxNames),
    f.in.type !== 'none' && [slider('Length s', at(f, 'in.dur'), { min: 0.1, max: 5, step: 0.05 }), slider('Start at s', at(f, 'in.delay'), { min: 0, max: S.p.stage.duration, step: 0.05 }),
      text && check('Letter by letter', at(f, 'in.letters')), text && (f.in.letters || f.in.type === 'typewriter') && slider('Letter delay', at(f, 'in.stagger'), { min: 0, max: 0.5 })],
    sec('2 · While on screen'), choose('Motion', at(f, 'loop.type'), Object.keys(LOOP_FX).filter(k => text || !LOOP_FX[k]?.letters)),
    f.loop.type !== 'none' && [slider('Speed', at(f, 'loop.speed'), { min: 0.1, max: 4 }), slider('Amount', at(f, 'loop.amount'), { min: 0, max: 3 })],
    sec('3 · Exit (how it leaves)'), choose('Effect', at(f, 'out.type'), fxNames),
    f.out.type !== 'none' && [slider('Length s', at(f, 'out.dur'), { min: 0.1, max: 5, step: 0.05 }),
      text && check('Letter by letter', at(f, 'out.letters')), text && (f.out.letters || f.out.type === 'typewriter') && slider('Letter delay', at(f, 'out.stagger'), { min: 0, max: 0.5 })]);
  put(el, sec('Keyframes (your own motion)'), keyHelp(o.keys),
    o.keys.length > 0 && h('div', { class: 'row' }, h('button', { onclick: () => { const p = evalPose(o, S.time); Object.assign(o, { pos: p.pos, rot: p.rot, scl: p.scl, opacity: p.op, keys: [] }); S.key = null; commit(); } }, 'Remove all keyframes')));
}
const keyHelp = keys => h('p', { class: 'hint' }, keys.length ? `${keys.length} keyframe${keys.length > 1 ? 's' : ''} (yellow diamonds below). Move the time line, then move the object: a keyframe is added for you. Click a diamond to change its speed curve or delete it.`
