export const IN_FX = {
  none: null,
  fade: () => {}, // opacity only (handled by the shared fade below)
  'fly left': (s, u) => { s.p[0] -= u * 14; },
  'fly right': (s, u) => { s.p[0] += u * 14; },
  'fly top': (s, u) => { s.p[1] += u * 9; },
  'fly bottom': (s, u) => { s.p[1] -= u * 9; },
  'from far': (s, u) => { s.p[2] -= u * 40; },
  'from near': (s, u) => { s.p[2] += u * 14; },
  zoom: (s, u) => { s.s *= 1 - u; },
  pop: (s, u, k) => { s.s *= EASE.back(k); },
  elastic: (s, u, k) => { s.s *= EASE.elastic(k); },
