// Export: PNG image, video (MP4 or WebM) and animated GIF. Frames are rendered one by one from the
// timeline, so the result is smooth even on a slow computer.
import { Muxer as Mp4Muxer, ArrayBufferTarget as Mp4Target } from 'mp4-muxer';
import { Muxer as WebmMuxer, ArrayBufferTarget as WebmTarget } from 'webm-muxer';
import { GIFEncoder, quantize, applyPalette } from 'gifenc';

const tick = () => new Promise(r => setTimeout(r, 0));
const toBlob = (canvas, type, q) => new Promise(r => canvas.toBlob(r, type, q));

export function exportImage(engine, { width, height, transparent, time, type = 'image/png' }) {
  return engine.withSize(width, height, async () => {
    engine.frame(time, { transparent: transparent && type === 'image/png' });
    return { blob: await toBlob(engine.canvas, type, 0.95), ext: type === 'image/jpeg' ? 'jpg' : 'png' };
  });
}

const CODECS = [
  { codec: 'avc1.640028', mux: 'mp4' }, { codec: 'avc1.42001f', mux: 'mp4' },
  { codec: 'vp09.00.40.08', mux: 'webm', id: 'V_VP9' }, { codec: 'vp8', mux: 'webm', id: 'V_VP8' },
];
export async function videoSupport(width, height, fps) {
  if (!('VideoEncoder' in window)) return null;
  for (const c of CODECS) {
    const cfg = { codec: c.codec, width, height, framerate: fps, bitrate: Math.round(Math.min(40e6, Math.max(1.5e6, width * height * fps * 0.13))) };
    try { if ((await VideoEncoder.isConfigSupported(cfg)).supported) return { ...c, cfg }; } catch (e) { /* try the next one */ }
  }
  return null;
}

export async function exportVideo(engine, { width, height, fps, duration, onProgress, isCancelled }) {
  width &= ~1; height &= ~1;                                   // H.264 needs even numbers
  const frames = Math.max(1, Math.round(duration * fps));
  const sup = await videoSupport(width, height, fps);
  if (!sup) return recordRealtime(engine, { width, height, fps, duration, onProgress, isCancelled });
  return engine.withSize(width, height, async () => {
    const mp4 = sup.mux === 'mp4';
    const muxer = mp4
      ? new Mp4Muxer({ target: new Mp4Target(), video: { codec: 'avc', width, height }, fastStart: 'in-memory' })
      : new WebmMuxer({ target: new WebmTarget(), video: { codec: sup.id, width, height, frameRate: fps } });
    let failed = null;
    const enc = new VideoEncoder({ output: (chunk, meta) => muxer.addVideoChunk(chunk, meta), error: e => { failed = e; } });
    enc.configure(sup.cfg);
    for (let i = 0; i < frames; i++) {
      if (failed) throw failed;
      if (isCancelled?.()) { enc.close(); return null; }
      engine.frame(i / fps);
      const vf = new VideoFrame(engine.canvas, { timestamp: Math.round(i * 1e6 / fps), duration: Math.round(1e6 / fps) });
      enc.encode(vf, { keyFrame: i % (fps * 2) === 0 }); vf.close();
      while (enc.encodeQueueSize > 6) await tick();
      onProgress?.((i + 1) / frames); await tick();
    }
    await enc.flush(); enc.close(); muxer.finalize();
    if (failed) throw failed;
    return { blob: new Blob([muxer.target.buffer], { type: mp4 ? 'video/mp4' : 'video/webm' }), ext: mp4 ? 'mp4' : 'webm' };
  });
}

// Fallback for browsers without WebCodecs: record the canvas while it plays in real time.
function recordRealtime(engine, { width, height, fps, duration, onProgress, isCancelled }) {
  const type = ['video/mp4;codecs=avc1', 'video/webm;codecs=vp9', 'video/webm'].find(t => window.MediaRecorder && MediaRecorder.isTypeSupported(t));
  if (!type) throw new Error('This browser cannot record video. Please use a current Chrome or Edge.');
  return engine.withSize(width, height, () => new Promise((resolve, reject) => {
    const rec = new MediaRecorder(engine.canvas.captureStream(fps), { mimeType: type, videoBitsPerSecond: 8e6 }), parts = [];
    rec.ondataavailable = e => e.data.size && parts.push(e.data);
    rec.onerror = e => reject(e.error || new Error('Recording failed'));
    rec.onstop = () => resolve(parts.length ? { blob: new Blob(parts, { type }), ext: type.includes('mp4') ? 'mp4' : 'webm' } : null);
    const t0 = performance.now(); rec.start();
    const step = () => {
      const t = (performance.now() - t0) / 1000;
      if (isCancelled?.()) { parts.length = 0; rec.stop(); return; }
      engine.frame(Math.min(t, duration)); onProgress?.(Math.min(1, t / duration));
      if (t >= duration) rec.stop(); else requestAnimationFrame(step);
    };
    step();
  }));
}

export function exportGIF(engine, { width, height, fps, duration, onProgress, isCancelled }) {
  const frames = Math.max(1, Math.round(duration * fps));
  return engine.withSize(width, height, async () => {
    const gif = GIFEncoder(), c2 = document.createElement('canvas'); c2.width = width; c2.height = height;
    const ctx = c2.getContext('2d', { willReadFrequently: true });
    for (let i = 0; i < frames; i++) {
      if (isCancelled?.()) return null;
      engine.frame(i / fps);
      ctx.clearRect(0, 0, width, height); ctx.drawImage(engine.canvas, 0, 0, width, height);
      const { data } = ctx.getImageData(0, 0, width, height), palette = quantize(data, 256);
      gif.writeFrame(applyPalette(data, palette), width, height, { palette, delay: Math.round(1000 / fps) });
      onProgress?.((i + 1) / frames); await tick();
    }
    gif.finish();
    return { blob: new Blob([gif.bytes()], { type: 'image/gif' }), ext: 'gif' };
  });
}

// Project data model: plain JSON, so a project can be saved, shared and re-opened as one file.
import { STYLES, PARTICLES } from './assets.js';

export const APP = 'aik-3d-studio';
export const uid = () => 'o' + Math.random().toString(36).slice(2, 8);
export const clone = x => JSON.parse(JSON.stringify(x));

export const SIZES = {
  'YouTube 1080p (1920×1080)': [1920, 1080],
  'HD 720p (1280×720)': [1280, 720],
  '4K (3840×2160)': [3840, 2160],
  'Shorts / Reels (1080×1920)': [1080, 1920],
  'Square (1080×1080)': [1080, 1080],
  'Thumbnail (1280×720)': [1280, 720],
  'Web banner (1200×400)': [1200, 400],
};

export const newStage = () => ({
  width: 1920, height: 1080, fps: 30, duration: 6,
  bg: { type: 'gradient', color: '#04060c', color2: '#16264a', image: null },
  ambient: 0.45, light: { intensity: 2.4, az: 30, el: 45, color: '#ffffff' },
  env: 1, shadows: true, floor: 'none', floorY: -1.6, fov: 35,
  glow: { on: false, strength: 0.45, radius: 0.3, threshold: 0.7 },
});

export const newProject = () => ({
  app: APP, version: 1, name: 'Untitled',
  stage: newStage(),
  camera: { pos: [0, 0.6, 13], target: [0, 0, 0], keys: [] },
  fonts: {},            // custom fonts uploaded by the user: name -> typeface JSON
  objects: [],
});

const newFx = () => ({
  in: { type: 'none', dur: 1, delay: 0, stagger: 0.06, letters: true },
  loop: { type: 'none', speed: 1, amount: 1 },
  out: { type: 'none', dur: 0.8, stagger: 0.04, letters: true },
});
const bevel = () => ({ on: true, size: 0.03, thick: 0.04, seg: 3 });
const NAMES = { text: 'Text', shape: 'Shape', solid: 'Solid', svg: 'Logo', image: 'Picture', particles: 'Particles' };

export function newObject(type, extra = {}) {
  const o = { id: uid(), type, name: NAMES[type], visible: true, pos: [0, 0, 0], rot: [0, 0, 0], scl: [1, 1, 1], opacity: 1, keys: [], fx: newFx() };
  if (type === 'text') Object.assign(o, { text: 'AIK 3D', font: 'helvetiker_bold', size: 1.6, depth: 0.5, bevel: bevel(), spacing: 0.02, lineGap: 1.2, align: 'center', mat: clone(STYLES.Gold) });
  if (type === 'shape') Object.assign(o, { shape: 'star', size: 2, depth: 0.4, bevel: bevel(), mat: clone(STYLES.Gold) });
  if (type === 'solid') Object.assign(o, { solid: 'sphere', size: 2, mat: clone(STYLES.Chrome) });
  if (type === 'svg') Object.assign(o, { svg: '', size: 4, depth: 0.3, bevel: bevel(), useColors: true, mat: clone(STYLES.Gold) });
  if (type === 'image') Object.assign(o, { image: '', size: 4 });
  if (type === 'particles') { const kind = PARTICLES[extra.kind] ? extra.kind : 'snow'; Object.assign(o, { kind, ...clone(PARTICLES[kind]) }); }
  const out = Object.assign(o, clone(extra));
  if (!extra.name) out.name = type === 'text' ? out.text.split('\n')[0].slice(0, 18) : type === 'shape' ? cap(out.shape) : type === 'solid' ? cap(out.solid) : type === 'particles' ? cap(out.kind) : out.name;
  return out;
}
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);

// Fill anything missing in a loaded project with defaults, so old or hand-written files still open.
function fill(t, d) {
  for (const k in d) {
    if (t[k] === undefined || t[k] === null && d[k] !== null) t[k] = clone(d[k]);
    else if (d[k] && typeof d[k] === 'object' && !Array.isArray(d[k]) && typeof t[k] === 'object') fill(t[k], d[k]);
  }
  return t;
}
export function normalize(p) {
  if (!p || p.app !== APP || !Array.isArray(p.objects)) throw new Error('This is not an Aik 3D Studio project file.');
  fill(p, newProject());
  p.objects = p.objects.filter(o => NAMES[o.type]).map(o => fill(o, newObject(o.type, o.kind ? { kind: o.kind } : {})));
  const ids = new Set();
  for (const o of p.objects) { if (ids.has(o.id)) o.id = uid(); ids.add(o.id); }
  return p;
}

// Pose with keyframes: editing at the playhead writes a keyframe when the object is already animated.
export const snap = (t, fps) => Math.round(t * fps) / fps;
export function keyAt(keys, t, fps) { return keys.find(k => Math.abs(k.t - t) < 0.5 / fps); }
export function upsertKey(keys, key, fps) {
  const k = keyAt(keys, key.t, fps);
  if (k) Object.assign(k, key); else { keys.push(key); keys.sort((a, b) => a.t - b.t); }
}

export class History {
  constructor() { this.stack = []; this.i = -1; }
  push(json) { if (this.stack[this.i] === json) return; this.stack.length = this.i + 1; this.stack.push(json); if (this.stack.length > 60) this.stack.shift(); this.i = this.stack.length - 1; }
  undo() { return this.i > 0 ? this.stack[--this.i] : null; }
  redo() { return this.i < this.stack.length - 1 ? this.stack[++this.i] : null; }
}

// Ready-made projects. Each one is just a small recipe that fills a new project.
import { newProject, newObject, clone } from './model.js';
