const fx = (i = 'none', l = 'none', o = 'none', x = {}) => ({
  in: { type: i, dur: 1, delay: 0, stagger: 0.06, letters: true, ...x.in },
  loop: { type: l, speed: 1, amount: 1, ...x.loop },
  out: { type: o, dur: 0.8, stagger: 0.04, letters: true, ...x.out },
});
const text = (t, style, extra = {}) => newObject('text', { text: t, mat: clone(STYLES[style]), ...extra });
const shape = (s, style, extra = {}) => newObject('shape', { shape: s, mat: clone(STYLES[style]), ...extra });
const parts = (kind, extra = {}) => newObject('particles', { kind, ...extra });
const T = (name, swatch, fn) => ({ name, swatch, make: () => { const p = newProject(); p.name = name; fn(p, p.stage); return p; } });

