:root{--bg:#000;--p1:#090b0f;--p2:#11151c;--p3:#1a202a;--line:#232b38;--tx:#e9eef5;--mut:#8593a6;--ac:#00e5ff;--ac2:#6dff8f;--warn:#ffb020;--bad:#ff4d6a;--nw:104px}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--bg);color:var(--tx);font:13px/1.35 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;overscroll-behavior:none}
button,input,select,textarea{font:inherit;color:inherit}
button{background:var(--p3);border:1px solid var(--line);border-radius:7px;padding:6px 10px;cursor:pointer;white-space:nowrap}
button:hover{border-color:var(--ac)}
button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--ac);outline-offset:1px}
button.primary{background:var(--ac);border-color:var(--ac);color:#001318;font-weight:700;box-shadow:0 0 14px #00e5ff55}
button.ico{min-width:32px;padding:6px 8px}
button.on{border-color:var(--ac);color:var(--ac);box-shadow:inset 0 0 0 1px var(--ac)}
button:disabled{opacity:.4;cursor:default}
input[type=text],input[type=number],select,textarea{background:var(--p2);border:1px solid var(--line);border-radius:6px;padding:5px 7px;min-width:0}
textarea{width:100%;resize:vertical;min-height:54px}
input[type=color]{width:34px;height:26px;padding:0;border:1px solid var(--line);border-radius:6px;background:none;cursor:pointer}
input[type=range]{accent-color:var(--ac);min-width:0;flex:1}
#app{display:grid;height:100dvh;grid-template:"top top top" auto "left stage right" minmax(0,1fr) "tl tl tl" auto / 178px minmax(0,1fr) 304px}
#top{grid-area:top;display:flex;align-items:center;gap:10px;padding:7px 10px;background:var(--p1);border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:7px;color:var(--ac);text-shadow:0 0 12px #00e5ff88;font-size:15px}
.brand b{color:var(--tx)}
#pname{flex:1;max-width:240px;background:transparent;border:1px solid transparent;border-radius:6px;padding:5px 7px;color:var(--mut)}
#pname:hover,#pname:focus{border-color:var(--line);color:var(--tx)}
.tools{margin-left:auto;display:flex;gap:6px;flex-wrap:nowrap}
#left{grid-area:left;background:var(--p1);border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0}
.adds{display:grid;grid-template-columns:1fr 1fr;gap:5px;padding:8px}
.adds button{padding:7px 4px;font-size:12px}
.list{flex:1;overflow:auto;padding:0 6px 8px}
.item{display:flex;align-items:center;gap:4px;padding:5px 6px;border-radius:7px;border:1px solid transparent;cursor:pointer}
.item:hover{background:var(--p2)}
.item.sel{background:var(--p3);border-color:var(--ac)}
.item .nm{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.item .ty{color:var(--mut);font-size:10px;text-transform:uppercase;letter-spacing:.04em}
.item button{padding:1px 5px;background:none;border-color:transparent;color:var(--mut)}
.item button:hover{color:var(--tx);border-color:var(--line)}
.item.off .nm{opacity:.4}
#stage{grid-area:stage;position:relative;min-width:0;min-height:0;background:repeating-conic-gradient(#0b0d11 0 25%,#07080b 0 50%) 0 0/22px 22px}
#frame{position:absolute;inset:10px;display:grid;place-items:center}
#view{display:block;box-shadow:0 0 0 1px var(--line),0 0 40px #00e5ff18;touch-action:none;background:repeating-conic-gradient(#2a2f38 0 25%,#1c2027 0 50%) 0 0/16px 16px}
.modes{position:absolute;left:14px;top:14px;display:flex;gap:5px;flex-wrap:wrap}
.modes button{background:#000b;backdrop-filter:blur(4px);padding:5px 9px;font-size:12px}
#right{grid-area:right;background:var(--p1);border-left:1px solid var(--line);display:flex;flex-direction:column;min-height:0}
#tabs{display:flex;border-bottom:1px solid var(--line)}
#tabs button{flex:1;border:0;border-radius:0;background:none;padding:9px 4px;color:var(--mut);border-bottom:2px solid transparent}
#tabs button.on{color:var(--ac);border-bottom-color:var(--ac);box-shadow:none}
#panel{flex:1;overflow:auto;padding:8px 10px 20px}
.sec{margin:12px 0 5px;color:var(--ac2);font-size:11px;letter-spacing:.08em;text-transform:uppercase}
.sec:first-child{margin-top:2px}
.row{display:flex;align-items:center;gap:7px;margin:5px 0}
.row>label{width:78px;flex:none;color:var(--mut)}
.row input[type=number]{width:62px;flex:none}
.row select,.row input[type=text]{flex:1}
.row3 input[type=number]{flex:1;width:0}
.hint{color:var(--mut);margin:8px 0;font-size:12px}
.grid{display:grid;gap:5px}
.styles{grid-template-columns:repeat(7,1fr)}
.sw{aspect-ratio:1;border-radius:7px;border:1px solid var(--line);padding:0;position:relative}
.sw:hover{transform:scale(1.08)}
.shapes{grid-template-columns:repeat(6,1fr)}
.shapes button{padding:4px;aspect-ratio:1}
.shapes svg{width:100%;height:100%;fill:var(--tx)}
.shapes button.on svg{fill:var(--ac)}
#tl{grid-area:tl;background:var(--p1);border-top:1px solid var(--line);min-width:0}
.tl-bar{display:flex;align-items:center;gap:8px;padding:6px 10px;flex-wrap:wrap}
#clock{font-variant-numeric:tabular-nums;color:var(--mut);min-width:96px}
#keytools{display:flex;gap:6px;align-items:center}
.tl-body{position:relative;max-height:150px;overflow-y:auto;padding-bottom:6px;user-select:none;-webkit-user-select:none}
.trow{display:flex;align-items:center;height:22px}
.trow .tn{width:var(--nw);flex:none;padding:0 6px 0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--mut);cursor:pointer;font-size:12px}
.trow.sel .tn{color:var(--ac)}
.lane{flex:1;position:relative;height:100%;margin-right:14px;border-bottom:1px solid #161b23;cursor:pointer;touch-action:none}
.trow.sel .lane{background:#00e5ff0d}
.ruler .lane{border-bottom:1px solid var(--line);cursor:ew-resize}
.tick{position:absolute;top:3px;font-size:10px;color:var(--mut);transform:translateX(-50%);pointer-events:none}
.tick::after{content:"";position:absolute;left:50%;top:13px;height:5px;border-left:1px solid var(--line)}
.fxbar{position:absolute;top:8px;height:6px;border-radius:3px;pointer-events:none;opacity:.75}
.fxbar.in{background:var(--ac2)}.fxbar.out{background:var(--bad)}.fxbar.loop{background:#3a4658;top:10px;height:2px}
.key{position:absolute;top:50%;width:11px;height:11px;margin:-5.5px 0 0 -5.5px;background:var(--warn);transform:rotate(45deg);border:1px solid #000;cursor:grab;touch-action:none}
.key.sel{background:#fff;box-shadow:0 0 8px #fff}
.key::before{content:"";position:absolute;inset:-7px}
#head{position:absolute;top:0;bottom:0;left:var(--nw);right:14px;pointer-events:none}
#head i{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--ac);box-shadow:0 0 8px var(--ac)}
#modal{position:fixed;inset:0;background:#000c;display:grid;place-items:center;z-index:20;padding:12px}
#modal[hidden],#toast[hidden]{display:none}
.dlg{background:var(--p1);border:1px solid var(--line);border-radius:12px;width:min(640px,100%);max-height:calc(100dvh - 24px);overflow:auto;padding:14px 16px;box-shadow:0 0 50px #00e5ff22}
.dlg h2{margin:0 0 10px;font-size:16px;display:flex;justify-content:space-between;align-items:center}
.dlg h3{margin:14px 0 4px;font-size:13px;color:var(--ac2)}
.dlg p,.dlg li{color:#c5cfdb}
.dlg ol,.dlg ul{padding-left:20px;margin:6px 0}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:9px}
.card{padding:0;overflow:hidden;text-align:left}
.card i{display:block;height:64px}
.card span{display:block;padding:6px 8px}
.choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:7px;margin:8px 0}
.choices button{padding:9px 6px;white-space:normal}
.choices small{display:block;color:var(--mut);font-size:11px}
.bar{height:8px;background:var(--p3);border-radius:4px;overflow:hidden;margin:10px 0}
.bar i{display:block;height:100%;width:0;background:var(--ac);box-shadow:0 0 10px var(--ac)}
.result{margin-top:10px}
.result img,.result video{max-width:100%;max-height:300px;display:block;margin:8px auto;border:1px solid var(--line);background:repeating-conic-gradient(#2a2f38 0 25%,#1c2027 0 50%) 0 0/16px 16px}
.result a{color:var(--ac);font-weight:700}
#draw{width:100%;max-width:380px;aspect-ratio:1;display:block;margin:8px auto;background:var(--p2);border:1px solid var(--line);border-radius:8px;touch-action:none;cursor:crosshair}
#toast{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);background:var(--p3);border:1px solid var(--ac);border-radius:9px;padding:8px 14px;z-index:30;max-width:92vw;box-shadow:0 0 20px #00e5ff33}
@media (max-width:860px){
  :root{--nw:74px}
  #app{grid-template:"top" auto "left" auto "stage" minmax(150px,36dvh) "tl" auto "right" minmax(0,1fr) / minmax(0,1fr)}
  #top{flex-wrap:wrap;gap:6px;padding:6px 8px}
  #pname{display:none}
  .tools{max-width:100%;gap:4px;margin-left:0;flex:1;justify-content:space-between}
  .tools button{padding:6px 7px;font-size:12px}
  .tools button.ico{min-width:28px}
  .brand{width:100%}
  #left{flex-direction:row;border-right:0;border-bottom:1px solid var(--line);overflow-x:auto}
  .adds{display:flex;padding:6px}
  .adds button{padding:6px 9px}
  .list{display:flex;gap:4px;padding:6px 6px 6px 0;overflow:visible}
  .item{flex:none;max-width:150px}
  .item .ty{display:none}
  #frame{inset:6px}
  #right{border-left:0;border-top:1px solid var(--line)}
  .tl-body{max-height:92px}
  .styles{grid-template-columns:repeat(8,1fr)}
  .shapes{grid-template-columns:repeat(8,1fr)}
}
@media (prefers-reduced-motion:reduce){.sw:hover{transform:none}}

// Builds the ready-to-host site into docs/ (GitHub Pages can serve that folder directly).
import { build, context } from 'esbuild';
import { cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const watch = process.argv.includes('--watch');
mkdirSync('docs', { recursive: true });
cpSync('public', 'docs', { recursive: true });
const options = { entryPoints: ['src/app.js'], bundle: true, format: 'iife', minify: !watch, sourcemap: watch, target: 'es2020', outfile: 'docs/app.js', logLevel: 'info', legalComments: 'none' };
if (watch) { const ctx = await context(options); await ctx.watch(); console.log('watching src/ …'); }
else {
  await build(options);
  // The same tool as ONE file: works by double-click, with no server and no internet.
  const js = readFileSync('docs/app.js', 'utf8').replace(/<\/script/gi, '<\\/script'), css = readFileSync('public/style.css', 'utf8');
  const html = readFileSync('public/index.html', 'utf8')
    .replace('<link rel="stylesheet" href="style.css">', () => `<style>${css}</style>`)
    .replace('<script src="app.js"></script>', () => `<script>${js}</script>`);
  if (html.includes('href="style.css"') || html.includes('src="app.js"')) throw new Error('single-file build: could not inline the page');
  writeFileSync('Aik-3D-Studio.html', html);
  console.log(`  Aik-3D-Studio.html  ${(html.length / 1048576).toFixed(1)}mb (single file)`);
}

// Tiny static server for docs/. Usage: node tools/serve.mjs [port]
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';

const port = +process.argv[2] || 5173, root = join(process.cwd(), 'docs');
const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png', '.map': 'application/json' };
createServer(async (req, res) => {
  const file = normalize(decodeURIComponent(new URL(req.url, 'http://x').pathname)).replace(/^([/\\]|\.\.)+/, '') || 'index.html';
  try {
    const body = await readFile(join(root, file));
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream', 'cache-control': 'no-store' }); res.end(body);
  } catch { res.writeHead(404, { 'content-type': 'text/plain' }); res.end('Not found'); }
}).listen(port, '0.0.0.0', () => console.log(`Aik 3D Studio: http://localhost:${port}`));

